-- Conferência.
do $$
begin
  raise notice 'Processos de carga: %', (select count(*) from public.mobilizacao_processos where origem = 'planilha');
end $$;

-- ----------------------------------------------------------------------------
-- RESPONSÁVEIS que a planilha cita, ainda como texto solto.
--
-- A planilha guarda só o primeiro nome ("Edijane", "Ivone"), e o banco quer
-- o id do colaborador. Todas são do time do Administrativo, então o de-para
-- casa com quem já tem administrativo_role. Rode o UPDATE abaixo depois de
-- conferir os nomes — a carga NÃO chuta ninguém.
--
--   Edijane
--
-- Exemplo:
--   update public.mobilizacao_processos p
--      set responsavel_id = (select id from public.colaboradores where nome ilike 'Edijane%' limit 1)
--    where p.origem = 'planilha' and p.responsavel_id is null;
-- ----------------------------------------------------------------------------
